153	const CREATE_TASK_INITIAL_SAVE: any = {
154	    siteType: '',
155	    linkedServices: [],
156	    recentClick: undefined,
157	    Mileage: '240',
158	    DueDate: undefined,
159	    dueDate: 'Today',
160	    taskCategory: '',
161	    taskCategoryParent: '',
162	    rank: '6',
163	    Time: 'Medium',
164	    taskName: '',
165	    taskUrl: undefined,
166	    portfolioType: 'Component',
167	    Component: [],
168	    Project: {},
169	    Description: [],
170	};
171	
172	const BURGER_QUERY_STOP_PARAMS = [
173	    'ToolTitle', 'TaskType', 'ComponentID', 'Type', 'ServiceID', 'TeamFeedback', 'TaskAction',
174	    'TaskId', 'Title', 'siteType', 'TaxType', 'DueDate', 'Priority', 'CreatedBy', 'CreatedDate',
175	    'Description', 'TaskUrl', 'ExternalSite', 'siteAbsoluteUrl', 'TaskSite', 'Email',
176	];
177	
178	function stripBurgerQuerySuffix(raw: string): string {
179	    if (!raw) {
180	        return raw;
181	    }
182	    let value = raw;
183	    for (const key of BURGER_QUERY_STOP_PARAMS) {
184	        const marker = `&${key}=`;
185	        const idx = value.indexOf(marker);
186	        if (idx > -1) {
187	            value = value.slice(0, idx);
188	        }
189	    }
190	    const hashIdx = value.indexOf('#/');
191	    if (hashIdx > -1) {
