const CREATE_TASK_INITIAL_SAVE: any = {
    siteType: '',
    linkedServices: [],
    recentClick: undefined,
    Mileage: '240',
    DueDate: undefined,
    dueDate: 'Today',
    taskCategory: '',
    taskCategoryParent: '',
    rank: '6',
    Time: 'Medium',
    taskName: '',
    taskUrl: undefined,
    portfolioType: 'Component',
    Component: [],
    Project: {},
    Description: [],
};

const BURGER_QUERY_STOP_PARAMS = [
    'ToolTitle', 'TaskType', 'ComponentID', 'Type', 'ServiceID', 'TeamFeedback', 'TaskAction',
    'TaskId', 'Title', 'siteType', 'TaxType', 'DueDate', 'Priority', 'CreatedBy', 'CreatedDate',
    'Description', 'TaskUrl', 'ExternalSite', 'siteAbsoluteUrl', 'TaskSite', 'Email',
];

function stripBurgerQuerySuffix(raw: string): string {
    if (!raw) {
        return raw;
    }
    let value = raw;
    for (const key of BURGER_QUERY_STOP_PARAMS) {
        const marker = `&${key}=`;
        const idx = value.indexOf(marker);
        if (idx > -1) {
            value = value.slice(0, idx);
        }
    }
    const hashIdx = value.indexOf('#/');
    if (hashIdx > -1) {
        value = value.slice(0, hashIdx);
    }
    return value.trim();
}

function normalizeBurgerTaskUrl(raw: string | undefined): string {
    const trimmed = stripBurgerQuerySuffix((raw || '').trim());
    if (!trimmed || trimmed === 'undefined') {
        return '';
    }
    if (/^https?:?\s*$/i.test(trimmed)) {
        return '';
    }
    if (/^https?:?&/i.test(trimmed)) {
        return '';
    }
    return trimmed;
}

function parseBurgerSiteUrlFromLocation(): string | undefined {
    const completeUrl = window.location.href;
    const siteUrlPart = completeUrl?.split("Siteurl=")[1] || completeUrl?.split("Siteurl")[1];
    if (siteUrlPart) {
        let siteUrlData = siteUrlPart.split('&OR')[0];
        if (siteUrlData.startsWith('=')) {
            siteUrlData = siteUrlData.slice(1);
        }
        if (siteUrlData) {
            try {
                const decoded = decodeURIComponent(siteUrlData);
                const normalized = normalizeBurgerTaskUrl(decoded);
                if (normalized) {
                    return normalized;
                }
            } catch {
                const normalized = normalizeBurgerTaskUrl(siteUrlData);
                if (normalized) {
                    return normalized;
                }
            }
        }
    }

    const params = new URLSearchParams(window.location.search);
    let fromParams = params.get('Siteurl') || undefined;
    if (fromParams && fromParams !== 'undefined' && fromParams !== '') {
        try {
            fromParams = decodeURIComponent(fromParams);
        } catch {
            /* already decoded */
        }
        const normalized = normalizeBurgerTaskUrl(fromParams);
        if (normalized) {
            return normalized;
        }
    }
    return undefined;
}

function resolveBurgerTaskUrl(component: any, rawSiteUrl: string | undefined, pageName?: string, siteBaseUrl?: string): string {
    const normalizedRawSiteUrl = normalizeBurgerTaskUrl(rawSiteUrl);
    if (normalizedRawSiteUrl) {
        return normalizedRawSiteUrl;
    }
    const foundation = component?.FoundationPageUrl;
    if (foundation) {
        const foundationUrl = typeof foundation === 'string'
            ? foundation
            : String(foundation?.Url || foundation?.Description || '');
        if (/^https?:\/\//i.test(foundationUrl)) {
            return foundationUrl;
        }
        const base = (siteBaseUrl || '').replace(/\/$/, '');
        if (base) {
            const path = foundationUrl.startsWith('/') ? foundationUrl : `/${foundationUrl}`;
            return `${base}${path}`;
        }
        return foundationUrl;
    }
    if (pageName && siteBaseUrl) {
        return `${siteBaseUrl.replace(/\/$/, '')}/SitePages/${pageName}`;
    }
    return rawSiteUrl || '';
}

function resolveSiteTypeFromComponent(component: any, sitesTypes: any[]): string {
    if (!component || !sitesTypes?.length) {
        return sitesTypes?.length === 1 ? sitesTypes[0]?.Title || '' : '';
    }

    const getSiteTitleMatch = (siteName: string | undefined): string => {
        if (!siteName) {
            return '';
        }
        const normalizedSiteName = String(siteName).toLowerCase();
        const found = sitesTypes.find((site: any) =>
            site?.Title?.toLowerCase() === normalizedSiteName ||
            site?.AlternativeTitle?.toLowerCase()?.split(';')?.some((alt: string) => alt?.toLowerCase() === normalizedSiteName)
        );
        return found?.Title || '';
    };

    const directSiteMatch =
        getSiteTitleMatch(component?.siteName) ||
        getSiteTitleMatch(component?.SiteName) ||
        getSiteTitleMatch(component?.siteType) ||
        getSiteTitleMatch(component?.SiteType) ||
        getSiteTitleMatch(component?.SiteTitle);
    if (directSiteMatch) {
        return directSiteMatch;
    }

    try {
        const tags = typeof component.Sitestagging === 'string'
            ? JSON.parse(component.Sitestagging)
            : component.Sitestagging;
        if (Array.isArray(tags)) {
            for (const tag of tags) {
                const matchedTitle = getSiteTitleMatch(tag?.Title || tag?.siteName);
                if (matchedTitle) {
                    return matchedTitle;
                }
            }
        }
    } catch (e) { }

    if (component.ClientCategory?.length) {
        for (const cc of component.ClientCategory) {
            const matchedTitle = getSiteTitleMatch(cc?.siteName || cc?.Title);
            if (matchedTitle) {
                return matchedTitle;
            }
        }
    }

    return resolveSiteTypeFromTaskUrl(
        typeof component?.FoundationPageUrl === 'string'
            ? component.FoundationPageUrl
            : String(component?.FoundationPageUrl?.Url || component?.FoundationPageUrl?.Description || ''),
        sitesTypes
    );
}

function resolveSiteTypeFromTaskUrl(taskUrl: string, sitesTypes: any[]): string {
    if (!taskUrl) {
        return sitesTypes?.length === 1 ? sitesTypes[0]?.Title || '' : '';
    }
    if (!sitesTypes || sitesTypes.length <= 1) {
        return sitesTypes?.length === 1 ? sitesTypes[0]?.Title || '' : '';
    }

    let testUrl = taskUrl;
    if (testUrl.toLowerCase().indexOf('.com') > -1) {
        testUrl = testUrl.split('.com')[1];
    } else if (testUrl.toLowerCase().indexOf('.ch') > -1) {
        testUrl = testUrl.split('.ch')[1];
    } else if (testUrl.toLowerCase().indexOf('.de') > -1) {
        const deParts = testUrl.split('.de');
        try {
            if (deParts[0]?.toLowerCase()?.indexOf('gruene-washington') > -1) {
                testUrl = deParts[0];
            } else {
                testUrl = deParts[1];
            }
        } catch (e) { }
    }

    const urlDataArr: any = testUrl.split('/');
    for (let index = 0; index < sitesTypes.length; index++) {
        const site = sitesTypes[index];
        let isFound = false;
        if (testUrl !== undefined && urlDataArr?.find((urlItem: any) => urlItem?.toLowerCase() == site?.Title?.toLowerCase()) || (site?.AlternativeTitle != null && urlDataArr?.find((urlItem: any) => urlItem?.toLowerCase() == site?.AlternativeTitle?.toLowerCase()))) {
            isFound = true;
            return site.Title;
        }
        if (!isFound && testUrl !== undefined && site.AlternativeTitle != null) {
            const sitesAlterNatives = site.AlternativeTitle.toLowerCase().split(';');
            for (let j = 0; j < sitesAlterNatives.length; j++) {
                const element = sitesAlterNatives[j];
                if (urlDataArr?.find((urlItem: any) => urlItem?.toLowerCase() == element?.toLowerCase())) {
                    return site.Title;
                }
            }
        }
    }
    return '';
}

