const createTask = async () => {
    const activeSave = pendingBurgerSave ? { ...save, ...pendingBurgerSave } : save;
    const activeTaskCat = (pendingBurgerTaskCat && pendingBurgerTaskCat.length > 0) ? pendingBurgerTaskCat : taskCat;
    let selectCategories: any = []
    let responsibleTeamIds: any[] = [];
    let currentUserId = loggedInUser?.AssingedToUserId
    var AssignedToIds: any[] = [];
    let MailArrayTitle: any[] = [];
    let ResponsibleIds: any = [];
    let Tasks: any = []
    if (!validateFormForSubmit()) {
        if (DirectTask) {
            clearCreateTaskSubmissionState();
        }
        return;
    }
    {
        setIsTaskCreated(true)
        let CategoryTitle: any;
        let TeamMembersIds: any[] = [];

        subCategories?.map((item: any) => {
            activeTaskCat?.map((cat: any) => {
                if (item.Id == cat) {
                    selectCategories.push(item)
                }
            })
            if (item.Title == "Design") {
                MailArrayTitle.push(item)
            }
        })
        selectCategories?.map((selectedCat: any) => {
            activeTaskCat?.map((cat: any) => {
                if (cat === selectedCat.Id) {
                    if (CategoryTitle === undefined) {
                        CategoryTitle = selectedCat.Title + ';';
                    } else {
                        CategoryTitle += selectedCat.Title + ';';
                    }

                }
            })
        })

        let ItemDetails: any = {}
        ItemDetails.TaskCategories = selectCategories
        ItemDetails.PercentComplete = 0
        ItemDetails.siteType = selectedSiteTitle;
        if (CategoryTitle?.indexOf("Design")> -1) {
            // data.data.TaskCategories = UXCat || []
            await GlobalFunctionForUpdateItems.TaskNotificationConfiguration({ usedFor: "Auto-Assignment", SiteURL: AllListId.siteUrl, ItemDetails: ItemDetails, Context: AllListId.Context, RequiredListIds: AllListId, AllTaskUser: taskUsers, Status: 0, setTaskAssignedTo: setTaskAssignedTo, setTaskResponsibleTeam: setTaskResponsibleTeam })
            taskAssignedTo?.forEach((users: any) => {
                assignedToIds?.push(users?.AssingedToUserId)
            })
            ItemDetails?.TaskResponsibleTeam?.map((LeadMember: any) => {
                responsibleTeamIds?.push(LeadMember.AssingedToUserId)
            })

        }

        if (CategoryTitle?.indexOf("User Experience - UX")> -1) {
            // data.data.TaskCategories = UXCat || []
            await GlobalFunctionForUpdateItems.TaskNotificationConfiguration({ usedFor: "Auto-Assignment", SiteURL: AllListId.siteUrl, ItemDetails: ItemDetails, Context: AllListId.Context, RequiredListIds: AllListId, AllTaskUser: taskUsers, Status: 0, setTaskAssignedTo: setTaskAssignedTo, setTaskResponsibleTeam: setTaskResponsibleTeam })
            taskAssignedTo?.forEach((users: any) => {
                assignedToIds?.push(users?.AssingedToUserId)
            })
            ItemDetails?.TaskResponsibleTeam?.map((LeadMember: any) => {
                responsibleTeamIds?.push(LeadMember.AssingedToUserId)
            })

        }
        let selectedCategory: any = [];
        let ApproverDataInfo: any = [];
        let CreateObject: any = {};
        try {
            selectedCategory = JSON?.parse(loggedInUser?.CategoriesItemsJson)
